// Copies the static renderer files into dist/renderer.
const fs = require('fs');
const path = require('path');

const src = path.join(__dirname, '..', 'src', 'renderer');
const dst = path.join(__dirname, '..', 'dist', 'renderer');

fs.rmSync(dst, { recursive: true, force: true });
fs.cpSync(src, dst, { recursive: true });

// Ship the app icon next to the renderer files so windows can reference it
// in dev and in packaged builds alike (build/icon.png is generated by make-icon.js).
const icon = path.join(__dirname, '..', 'build', 'icon.png');
if (fs.existsSync(icon)) fs.copyFileSync(icon, path.join(dst, 'icon.png'));

console.log('renderer copied to', dst);
